test('readiness completes its observation naturally while preserving a reused original tab',()=>{
 const prompt=studioPreviewPrompt('preview-readiness',browserInput());
 assert.match(prompt,/Immediately after emitting the one actual final OBSERVATION marker[\s\S]*final response and end the turn naturally/);
 assert.match(prompt,/do not make further checks or wait for the parent watchdog/);
 assert.match(prompt,/Never call markDeliverable\(\) or markHandoff\(\)/);
 assert.match(prompt,/With one or more exact candidates[\s\S]*cua\.getTab\(observedTabId,\{browser:chromeId\}\)/);assert.match(prompt,/For exactly zero candidates in a verified inventory[\s\S]*COMPLETE about:blank creation and same-call registration[\s\S]*navigate this original owned handle to boundDraftURL in its OWN invocation/);assert.match(prompt,/every existing reused or provider-locked page is never closed or marked/);
});

test('readiness closes only its own newly created temporary tab and cannot force another session release',()=>{
 const prompt=studioPreviewPrompt('preview-readiness',browserInput());
 assert.match(prompt,/Only if this session itself created a dedicated temporary tab may it close that same temporary tab in a finally block/);
 assert.match(prompt,/Never close an original user tab or another session's tab/);
 assert.match(prompt,/never claim or take over a tab owned by another session/);
 assert.match(prompt,/There is no documented finalizeTabs, releaseTab or endSession API/);
 assert.match(prompt,/every existing reused or provider-locked page is never closed or marked/);assert.match(prompt,/do not advance to another candidate, create a page, reconnect, force-claim or use a fallback/);
});

test('readiness stops once on tool or ownership failure and cannot report unobserved success',()=>{
 const prompt=studioPreviewPrompt('preview-readiness',browserInput());
 assert.match(prompt,/any connection, browser tool, tab ownership or draft-read error[\s\S]*report its concrete reason once[\s\S]*end the turn naturally/);
 assert.match(prompt,/Do not loop, reconnect, retry a claim, open replacement tabs/);
 assert.match(prompt,/On failure emit no OBSERVATION marker/);
 assert.match(prompt,/never fill its fields from the requested input as if they were observed/);
 assert.match(prompt,/never invent an observation to acknowledge a failed or unreadable check/);
 // Cleanup guidance is specific to the short read-only check. The actual Play
 // phase must retain its independent one-click and audio-waiting contract.
 const preview=studioPreviewPrompt('preview',browserInput());
 assert.doesNotMatch(preview,/NORMAL TAB CLEANUP/);
 assert.match(preview,/AUDIO PREVIEW Play exactly ONCE/);
 assert.match(preview,/Then wait by fresh UI\/DOM reads/);
});

