test('a bounded readiness timeout retains the same original request and unconsumed Play opportunity',async t=>{
 const f=fixture(t);let plays=0,disconnected=true;
 const browser=async(phase,input,options)=>{
  if(phase==='preview-readiness'&&disconnected)return runStudioPreviewBrowser(phase,input,{...options,child:async(_args,o)=>{
   assert.ok(o.deadline<=Date.now()+210000);o.stdout(Buffer.from(JSON.stringify({type:'thread.started',thread_id:'SYNTHETIC-readiness-timeout'})+'\n'));
   return{exit_code:null,timed_out:true};
  }});
  if(phase==='preview'){plays++;if(plays===1)return runStudioPreviewBrowser(phase,input,{...options,child:failureBeforeTools});writeClickJournal(input);}
  return observation(phase);
 };
 f.setAdapter(f.make({browser}));await f.quoted();await assert.rejects(f.generate,/BROWSER_RESULT_UNKNOWN/);f.request.status='provider_unknown';f.request.lease_until=null;
 const dir=path.resolve(f.root,'.sites-runtime/authorized-inputs',ID,'revision-2/automatic-clone',RID),files=['studio-draft.json','preview-play-intent.json','preview-acquisition-intent.json'],original=new Map(files.map(file=>[file,fs.readFileSync(path.join(dir,file))])),request=structuredClone(f.request);
 const adapter=f.make({browser});await assert.rejects(()=>adapter.resumeUnstarted({job:f.job,request:f.request}),/BROWSER_RESULT_UNKNOWN/);
 assert.deepEqual(f.request,request);for(const[file,bytes]of original)assert.deepEqual(fs.readFileSync(path.join(dir,file)),bytes);
 assert.equal(adapter.canResumeUnstarted({job:f.job,request:f.request}),true);assert.equal(plays,1);
 disconnected=false;const result=await adapter.resumeUnstarted({job:f.job,request:f.request});assert.equal(result.audio_sha256,speechSha(bytes));assert.equal(plays,2);
});

