function knownPrefixObservation(input){return{...zeroSearchObservation(input),pending_inventory:{...pendingPreparationInventory(input),inventory_mode:'known-other-prefix-v1',scope_continuity_verified:true,prefix_starts_at_latest:true,prefix_contiguous:true,recent_prefix:[{rank:0,draft_id:knownOtherDraft},{rank:1,draft_id:unknownBoundaryDraft}]}};}
