 const protectedNames=['preview-prepared-draft.json','studio-draft.json','preview-acquisition-intent.json','preview-play-intent.json',eh.failed+'/browser-events.json',eh.failed+'/browser-events.ndjson'],protectedBytes=Object.fromEntries(protectedNames.map(name=>[name,fs.readFileSync(path.join(h.dir,name))])),calls=[],reads=[],state={timeout:timeoutTransfer};
