for(const existingAudio of [false,true])test('provider direct-access origin continues only the matching v2 grant with '+(existingAudio?'zero extra Play for existing exact audio':'one separate once-only extra Play')+' while transfer stays zero',async t=>{const h=await providerEditorFixture(t,{directAccess:true});assert.equal(await h.f.reconcile(),null);assert.equal(h.f.make({readPreparedOwner:h.readPreparedOwner}).canResumeUnstarted({job:h.f.job,request:h.f.request}),true);assert.equal(fs.existsSync(path.join(h.dir,OWNER_PREVIEW_AUTHORIZATION_FILE)),true);const calls=[];const adapter=h.f.make({readPreparedOwner:h.readPreparedOwner,browser:async(phase,input,options)=>{calls.push({phase,input});assert.equal(input.provider_editor_continuation_permit,undefined);const o={...observation(phase),preview_audio_verified:true};let playMarker;if(phase==='preview-readiness'){assert.equal(input.owner_preview_readiness,true);if(existingAudio)Object.assign(o,{readyState:4,duration_seconds:2.5,url});}else{assert.equal(phase,'preview');assert.equal(input.owner_extra_preview,true);playMarker=ownerContinuationMarker(input);}return runStudioPreviewBrowser(phase,input,{...options,child:recordedSyntheticChild(ownerContinuationChild(input,o,{playMarker}))});},deadline_ms:Date.now()+3600000});assert.equal(adapter.canResumeUnstarted({job:h.f.job,request:h.f.request}),true);const result=await adapter.resumeUnstarted({job:h.f.job,request:h.f.request});assert.equal(result.audio_sha256,speechSha(bytes));assert.equal(fs.existsSync(h.editorJournal),false);assert.equal(fs.existsSync(h.transfer),false);assert.equal(calls.filter(c=>c.phase==='preview').length,existingAudio?0:1);assert.equal(fs.existsSync(path.join(h.dir,OWNER_PREVIEW_CONTINUATION_JOURNAL)),!existingAudio);assert.equal(fs.existsSync(path.join(h.dir,OWNER_EXTRA_PLAY_OBSERVED_FILE)),!existingAudio);assert.deepEqual(await adapter.reconcile({job:h.f.job,request:h.f.request}),result);assert.equal(calls.filter(c=>c.phase==='preview').length,existingAudio?0:1);for(const [name,bytes]of Object.entries(h.protectedBytes))assert.deepEqual(fs.readFileSync(path.join(h.dir,name)),bytes,name);});

